CREATE INDEX "prospect_documents_student_idx" ON "prospect_documents" USING btree ("institution_id","student_id") WHERE "prospect_documents"."student_id" is not null;--> statement-breakpoint
ALTER TABLE "prospect_document_consents" ADD CONSTRAINT "prospect_document_consents_link_check" CHECK (("prospect_document_consents"."student_id" is null) = ("prospect_document_consents"."linked_at" is null));--> statement-breakpoint
ALTER TABLE "prospect_documents" ADD CONSTRAINT "prospect_documents_link_check" CHECK (("prospect_documents"."student_id" is null) = ("prospect_documents"."linked_at" is null) and ("prospect_documents"."student_id" is null) = ("prospect_documents"."linked_by_user_id" is null));--> statement-breakpoint
ALTER TABLE "prospect_documents" ADD CONSTRAINT "prospect_documents_link_status_check" CHECK ("prospect_documents"."student_id" is null or "prospect_documents"."status" in ('accepted', 'superseded'));--> statement-breakpoint
COMMENT ON TABLE "prospect_documents" IS 'Adaya eklenen belge (DOM-KAY-043, ON-263): platform dosyasına (files, amaç document) bağ ve inceleme durumu. Aday records''tadır (yabancı anahtar yok). Türde tek güncel belge; aynı türe yeni yükleme öncekini superseded yapar ve eski dosyanın imhası 30 gün sonraya işaretlenir (K-323). Kesin kayıtta kabul edilmiş belge öğrenci dosyasına bağlanır (student_id; DOM-KAY-045, K-384): dosya kopyalanmaz, bağlı belgenin dosyası imha işinde bekletilir. Dosya içeriği bu tabloda değildir.';--> statement-breakpoint
COMMENT ON COLUMN "prospect_documents"."student_id" IS 'Kesin kayıtla belgenin bağlandığı öğrenci (records, collection students, id; DOM-KAY-045, K-384). Yalnız kabul edilmiş belgede yazılır; yerine yenisi yüklenince bağ geçmiş olarak kalır, rıza geri çekilince belge arşivlenir. Bağlı, kabul edilmiş ve arşivlenmemiş belgenin dosyası imha edilmez. Kişisel veri sınıfı K.';--> statement-breakpoint
COMMENT ON COLUMN "prospect_documents"."linked_at" IS 'Belgenin öğrenciye bağlandığı an (UTC): kesin kayıt ya da kayıttan sonraki kabul; student_id ile birlikte dolu (prospect_documents_link_check).';--> statement-breakpoint
COMMENT ON COLUMN "prospect_documents"."linked_by_user_id" IS 'Bağı kuran işlemi yapan kullanıcı (kesin kaydı ya da kabulü yapan; Better Auth users.id); student_id ile birlikte dolu.';--> statement-breakpoint
COMMENT ON COLUMN "prospect_document_consents"."student_id" IS 'Kesin kayıtla rızanın bağlandığı öğrenci (records, collection students, id; DOM-KAY-045, K-385, H-80): öğrenciye bağlanan özel nitelikli belgenin işleme şartı. Kayıttan sonra kaydedilen rıza da bağlanır. Kişisel veri sınıfı K.';--> statement-breakpoint
COMMENT ON COLUMN "prospect_document_consents"."linked_at" IS 'Rızanın öğrenciye bağlandığı an (UTC); student_id ile birlikte dolu (prospect_document_consents_link_check).';
